// Light in-workflow filter mirroring pipeline/filter_jobs.py.
// Regenerated by pipeline/config_to_n8n.py --write — do not edit by hand.
const EXCLUDE_COMPANY = ["hays", "michael page", "page personnel", "robert half", "robert walters", "randstad", "adecco", "manpower", "expectra", "modis", "akkodis", "alten", "altran", "capgemini", "sopra steria", "atos", "cgi", "accenture", "devoteam", "talan", "wavestone", "mc2i", "extia", "amaris", "davidson", "free-?lance\\.com", "freelance republik", "malt", "comet", "lehibou", "club freelance", "mindquest", "huxley", "nigel frank"];
const EXCLUDE_TITLE = ["intern(ship)?", "stage|stagiaire", "alternan(ce|t)", "apprenti", "junior", "graduate", "working student"];
const seen = new Set();
return items.filter((item) => {
  const j = item.json;
  const id = String(j.id || j.jobId || j.url || Math.random());
  if (seen.has(id)) return false;
  seen.add(id);
  const company = String(j.companyName || j.company || "").toLowerCase();
  const title = String(j.title || "").toLowerCase();
  if (EXCLUDE_COMPANY.some((p) => new RegExp(p, "i").test(company))) return false;
  if (EXCLUDE_TITLE.some((p) => new RegExp(p, "i").test(title))) return false;
  return true;
});
